  [4731] = { "Insegna al tuo orso addomesticato l'abilità Morso Rabbioso. Morso Rabbioso riduce la resistenza di un nemico agli attacchi fisici e ne attira l'attenzione.\nRichiede: \nLivello del famiglio $N1+", nil, 0xaa9eb026, nil, "um" },
  [4732] = { "Insegna al tuo orso addomesticato l'abilità Roar of Fortitude. Roar of Fortitude aumenta la salute massima di tutti i membri del tuo gruppo.\nRichiede: \nLivello del famiglio $N1+", nil, 0x1c13d922, nil, "um" },
  [4733] = { "Insegna al tuo cinghiale addomesticato l'abilità Sbudellamento. Sbudellamento infligge danni fisici periodici a un nemico.\nRichiede: \nLivello del famiglio $N1+", nil, 0x6b6d5fe0, nil, "um" },
  [4734] = { "Insegna al tuo cinghiale addomesticato l'abilità Pelle Rinforzata. Pelle Rinforzata aumenta la resistenza agli attacchi fisici.\nRichiede: \nLivello del famiglio $N1+", nil, 0x38bf9609, nil, "um" },
  [4735] = { "Insegna al tuo cinghiale addomesticato l'abilità Vital Wound. Vital Wound rallenta la velocità d'attacco di un nemico.\nRichiede: \nLivello del famiglio $N1+", nil, 0x72e2e4a8, nil, "um" },
  [4736] = { "Insegna al tuo uccello addomesticato l'abilità ⟦Flight of the Peregrine=Volo del Pellegrino⟧. ⟦Flight of the Peregrine=Volo del Pellegrino⟧ aumenta la velocità di movimento dell'uccello.\nRichiede: \nLivello del famiglio $N1+", nil, 0x44d34f6f, nil, "um" },
  [4737] = { "Insegna al tuo uccello addomesticato l'abilità ⟦Eye Peck=Beccata⟧. ⟦Eye Peck=Beccata⟧ fa sì che un nemico manchi più spesso i suoi colpi in combattimento.\nRichiede: \nLivello del famiglio $N1+", nil, 0x30da3f71, nil, "um" },
  [4740] = { "Insegna al tuo felino addomesticato l'abilità Ferocia. Ferocia aumenta la velocità d'attacco del felino, al costo di subire più danni dagli attacchi fisici.\nRichiede: \nLivello del famiglio $N1+", nil, 0xb25f5e2b, nil, "um" },
  [4741] = { "Insegna al tuo felino addomesticato l'abilità Ferita Aperta. Ferita Aperta infligge danni fisici periodici a un nemico e aumenta per breve tempo i danni che subisce dagli attacchi fisici.\nRichiede: \nLivello del famiglio $N1+", nil, 0xc0a030b9, nil, "um" },
  [4742] = { "Insegna al tuo granchio addomesticato l'abilità Tough Shell. Tough Shell conferisce al tuo granchio una probabilità di aumentare il proprio valore di Armatura quando viene colpito.\nRichiede: \nLivello del famiglio $N1+", nil, 0xa61ec09a, nil, "um" },
  [4743] = { "Insegna al tuo granchio addomesticato l'abilità Tough Shell. Tough Shell conferisce al tuo granchio una probabilità di aumentare il proprio valore di Armatura quando viene colpito.\nRichiede: \nLivello del famiglio $N1+", nil, 0xa61f029d, nil, "um" },
  [4744] = { "Insegna al tuo granchio addomesticato l'abilità Tough Shell. Tough Shell conferisce al tuo granchio una probabilità di aumentare il proprio valore di Armatura quando viene colpito.\nRichiede: \nLivello del famiglio $N1+", nil, 0xa61f0632, nil, "um" },
  [4745] = { "Insegna al tuo granchio addomesticato l'abilità Tough Shell. Tough Shell conferisce al tuo granchio una probabilità di aumentare il proprio valore di Armatura quando viene colpito.\nRichiede: \nLivello del famiglio $N1+", nil, 0xa61f4835, nil, "um" },
  [4746] = { "Insegna al tuo granchio addomesticato l'abilità Tight Pinch. Tight Pinch infligge danni aggiuntivi al prossimo colpo del granchio e stordisce il nemico.\nRichiede:\nLivello del famiglio $N1+", nil, 0x223cab29, nil, "um" },
  [4747] = { "Insegna al tuo granchio addomesticato l'abilità Clenched Pinchers. Clenched Pinchers immobilizza un nemico infliggendogli danni fisici nel tempo. Mentre trattiene il nemico, il granchio non può attaccare né compiere altre azioni.\nRichiede:\nLivello del famiglio $N1+", nil, 0x2623d934, nil, "um" },
  [4748] = { "Insegna al tuo crocolisco addomesticato l'abilità Pinzata Rapida. Pinzata Rapida dà al tuo crocolisco una probabilità di contrattaccare quando viene colpito.\nRichiede:\nLivello del famiglio $N1+", nil, 0xdab0c6cb, nil, "um" },
  [4750] = { "Insegna al tuo crocolisco addomesticato l'abilità ⟦Consume Flesh=Consuma Carne⟧. ⟦Consume Flesh=Consuma Carne⟧ dà al tuo crocolisco una probabilità di sottrarre salute a un nemico quando attacca.\nRichiede:\nLivello del famiglio $N1+", nil, 0xfbdec489, nil, "um" },
