  [4766] = { "Insegna al tuo cavallo addomesticato l'abilità ⟦Rapid Gallop=Galoppo Rapido⟧. ⟦Rapid Gallop=Galoppo Rapido⟧ aumenta la velocità di movimento del tuo cavallo.\nRichiede:\nLivello del famiglio $N1+", nil, 0xe70b7485, nil, "um" },
  [4767] = { "Insegna al tuo cavallo addomesticato l'abilità Urto a Terra. Urto a Terra infligge danni aggiuntivi e rallenta la velocità di movimento del nemico.\nRichiede:\nLivello del famiglio $N1+", nil, 0x02a7e455, nil, "um" },
  [4768] = { "Insegna al tuo raptor addomesticato l'abilità Feast of Prey. Feast of Prey permette al tuo raptor di recuperare salute ogni volta che uccide un nemico.\nRichiede:\nLivello del famiglio $N1+", nil, 0x6b217642, nil, "um" },
  [4769] = { "Insegna al tuo raptor addomesticato l'abilità Vulnerabilità. Vulnerabilità aumenta per breve tempo tutti i danni fisici inflitti a un nemico.\nRichiede:\nLivello del famiglio $N1+", nil, 0xa544ec19, nil, "um" },
