  [4774] = { "Insegna al tuo gorilla addomesticato l'abilità Ammaccatura. Ammaccatura dà al tuo gorilla una probabilità di ridurre l'Armatura di un nemico quando attacca.\nRichiede:\nLivello del famiglio $N1+", nil, 0xab47339e, nil, "um" },
  [4775] = { "Insegna al tuo gorilla addomesticato l'abilità ⟦Throw Rock=Lancio Sasso⟧. ⟦Throw Rock=Lancio Sasso⟧ è un attacco a distanza.\nRichiede:\nLivello del famiglio $N1+", nil, 0x77dc06df, nil, "um" },
  [4777] = { "Insegna al tuo gorilla addomesticato l'abilità Rapidità. Rapidità è un attacco che può colpire più nemici.\nRichiede:\nLivello del famiglio $N1+", nil, 0xe64a5ebb, nil, "um" },
